def encode(message):
    vowels = 'aeiou'
    encoded_chars = []

    for char in message:
        if char.islower():
            new_char = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
            encoded_chars.append(new_char)
        elif char.isupper():
            new_char = chr((ord(char) - ord('A') + 2) % 26 + ord('A'))
            encoded_chars.append(new_char)
        elif char in vowels:
            new_char = chr(ord(char) + 2)
            encoded_chars.append(new_char)
        else:
            encoded_chars.append(char)

    return ''.join(encoded_chars)

